with new_company as (
  insert into portfolio_companies (
    name, slug, short_description_ar, short_description_en, description_ar, description_en,
    website_url, relationship_type, industry_ar, industry_en, founded_year, status, markets, is_published, sort_order,
    cover_image
  ) values (
    'Ektsab',
    'ektsab',
    'منصة رقمية تربط رواد الأعمال بخبراء متخصصين للحصول على استشارات عملية تحل تحديات مشاريعهم مباشرة.',
    'A platform connecting entrepreneurs with specialized experts for practical advice that solves their real challenges.',
    'اكتساب منصة تتيح لرواد الأعمال وأصحاب المشاريع الوصول المباشر إلى خبراء متخصصين في مجالاتهم، للاستفادة من خبراتهم وتجاربهم العملية في حل التحديات التي تواجه مشاريعهم واتخاذ قرارات أفضل. المنصة مملوكة بالكامل لتايسونستا، وتأسست من الصفر بدون تمويل خارجي.',
    'Ektsab gives entrepreneurs and business owners direct access to experts in their field, so they can draw on real experience to solve the challenges facing their projects and make better decisions. The platform is fully owned by Taysonsta and was built from the ground up with no outside funding.',
    'https://ektsab.com/ar',
    'owned',
    'استشارات وخبرات',
    'Expert Consulting',
    2026,
    'active',
    array['Egypt'],
    true,
    1,
    'img/portfolio-companies/ektsab-cover.png'
  )
  returning id
)
