insert into career_jobs (
  title, slug, team, location, employment_type, summary, role_description, ideal_candidate,
  requirements, responsibilities, disqualifiers, is_published, published_at
) values
(
  'Account Manager', 'account-manager', 'Client Services', 'Remote', 'Full-time',
  $$نبحث عن Account Manager يكون مسؤولًا عن إدارة العلاقة بين العميل وفريق التنفيذ، وضمان تنفيذ كل مشروع حسب الـScope والـTimeline والجودة المتفق عليها. هذا الدور هو حلقة الوصل الأساسية بين العميل والشركة بعد إتمام عملية البيع.$$,
  $$ستستلم العميل من Sales، وتحول ما تم الاتفاق عليه إلى خطة تنفيذ واضحة للفريق والعميل. ستكون مسؤولًا عن: Client Onboarding، Project Coordination، Communication، Timelines، Deliverables، Approvals، متابعة الفريق، متابعة العميل، حل المشاكل التشغيلية، والتأكد من تسليم الخدمة بالشكل الصحيح.$$,
  $$شخص منظم جدًا، قوي في التواصل، ويستطيع إدارة عدة مشاريع وعملاء في نفس الوقت بدون فقدان التفاصيل. لديك عقلية Ownership وتتعامل مع المشروع وكأنه مشروعك.$$,
  $$خبرة في Account Management أو Project Management. مهارات تواصل قوية. تنظيم ممتاز. القدرة على إدارة عدة عملاء. خبرة في أدوات إدارة المشاريع وCRM. القدرة على كتابة ومتابعة الـTasks. القدرة على التعامل مع العملاء باحترافية. فهم أساسي للتسويق والخدمات الرقمية. القدرة على حل المشاكل بسرعة.$$,
  $$استلام العملاء من Sales. تنفيذ Client Onboarding. إنشاء Project Plan. توزيع المهام على فريق التنفيذ. متابعة الـDeadlines. متابعة Deliverables. إدارة Feedback والـApprovals. التواصل المستمر مع العميل. تحديث حالة المشروع داخل Dashboard. تصعيد المشاكل عند الحاجة. التأكد من الالتزام بالـScope. اكتشاف فرص الـUpsell والـRenewal. إعداد تقارير عن حالة العملاء والمشاريع.$$,
  $$لا تحب التعامل المباشر مع العملاء. غير منظم. تضيع التفاصيل والمواعيد. تنتظر أن يخبرك الجميع بما يجب فعله. لا تستطيع إدارة أكثر من مشروع في نفس الوقت. لا تتحمل مسؤولية حل المشاكل. ترى أن دور Account Manager مجرد نقل الرسائل بين العميل والفريق.$$,
  true, now()
),
(
  'Content Manager', 'content-manager', 'Content', 'Remote', 'Full-time',
  $$نبحث عن Content Manager يقود عملية إنتاج المحتوى بالكامل حول الـPersonal Brand الخاص بمؤسس الشركة. المحتوى هو محرك النمو الرئيسي للشركة، وسيتم استخدامه لجذب الجمهور وبناء الثقة وتحويل المتابعين إلى عملاء لخدمات واشتراكات وأي عروض مستقبلية.$$,
  $$ستكون مسؤولًا عن تحويل خبرة المؤسس وأفكاره وتجربته إلى نظام محتوى مستمر وقابل للقياس. ستعمل على: بناء Content Strategy، Research واكتشاف المواضيع والفرص، بناء Content Calendar، تطوير الأفكار والـHooks، تحويل أفكار المؤسس إلى Briefs واضحة، التنسيق مع Video Editor وGraphic Designer، تحليل أداء المحتوى، تحديد أنواع المحتوى التي تحقق Views وFollowers وLeads وSales، إعادة استخدام المحتوى الناجح على أكثر من منصة، وبناء نظام إنتاج محتوى قابل للتوسع.$$,
  $$شخص يفهم أن الهدف من المحتوى ليس الحصول على Views فقط، بل بناء Audience يمكن تحويله إلى Business. لديك عقلية Growth، وتستطيع فهم شخصية المؤسس وتحويل خبرته إلى محتوى قوي بدون أن تجعل المحتوى يبدو مصطنعًا أو منفصلًا عن شخصيته.$$,
  $$خبرة في Content Strategy وإدارة المحتوى. فهم قوي لـShort-form Content. فهم للـHooks وRetention وStorytelling. القدرة على تحليل بيانات المحتوى. معرفة TikTok وInstagram وYouTube Shorts. قدرة قوية على Research. تنظيم ممتاز وإدارة Content Calendar. فهم أساسي للتسويق والـFunnels والـConversion. القدرة على العمل بسرعة وباستقلالية.$$,
  $$بناء خطة المحتوى الشهرية. تجهيز الأفكار والـBriefs. Research للمواضيع والاتجاهات. تنظيم جلسات التصوير. تجهيز قائمة الفيديوهات المطلوبة. متابعة إنتاج المحتوى. تحليل أداء كل Content Piece. استخراج الأفكار الناجحة وإعادة تطويرها. تحويل المحتوى إلى فرص Leads وSales. بناء نظام Documentation وSOPs لعملية المحتوى.$$,
  $$تعتبر أن المحتوى مجرد نشر بوستات. تركيزك الأساسي على عدد الـViews فقط. لا تستطيع العمل بالأرقام. تحتاج إلى أن يخبرك شخص بكل فكرة تعمل عليها. لا تعرف كيف تحول فكرة واحدة إلى عدة قطع محتوى. لا تستطيع العمل في بيئة سريعة ومتغيرة.$$,
  true, now()
),
(
  'Graphic Designer', 'graphic-designer', 'Creative', 'Remote', 'Full-time',
  $$نبحث عن Graphic Designer ينضم إلى فريق المحتوى والتسويق لتحويل الأفكار والاستراتيجيات إلى Visuals قوية تساعد على جذب الانتباه وبناء العلامة التجارية وتحسين أداء الإعلانات والمحتوى.$$,
  $$ستكون مسؤولًا عن التصميمات المرتبطة بالمحتوى والإعلانات والـMarketing Assets.$$,
  $$مصمم لديه حس تجاري، وليس مجرد مصمم ينفذ المطلوب. يفهم الفرق بين تصميم جميل وتصميم يؤدي وظيفة واضحة: Attention → Engagement → Action.$$,
  $$خبرة قوية في Graphic Design. Portfolio قوي. خبرة في Social Media Design. معرفة جيدة بـAdobe Photoshop / Illustrator أو الأدوات البديلة. فهم للـTypography والـComposition والـBranding. سرعة في التنفيذ. القدرة على الالتزام بالـBrand Guidelines. فهم أساسي للـPerformance Creatives.$$,
  $$تصميم Social Media Creatives. تصميم Ad Creatives. تصميم Thumbnails. تصميم Carousels. تصميم Presentations. تجهيز Visual Assets للمحتوى. اختبار Variations مختلفة من الـCreatives. التعاون مع Content Manager وVideo Editor وMarketing Manager. تطوير Visual Identity للمحتوى والحملات. تنظيم ملفات التصميم والـAssets.$$,
  $$تعتمد على تنفيذ التصميمات بدون فهم الهدف منها. لا تمتلك Portfolio قوي. لا تستطيع تنفيذ أكثر من Concept بسرعة. لا تهتم بالأداء والنتائج. لا تستطيع الالتزام بنظام Brand واضح. تبحث عن وظيفة تعتمد على تصميمات روتينية فقط.$$,
  true, now()
),
(
  'Head of Marketing', 'head-of-marketing', 'Marketing', 'Remote', 'Full-time',
  $$نبحث عن شخص يقود التسويق بالكامل داخل الشركة، ويكون مسؤولًا عن تحويل استراتيجية الشركة وعروضها إلى نظام تسويق متكامل يحقق نموًا مستمرًا في العملاء والمبيعات. هذا الدور ليس مجرد إدارة فريق أو متابعة وكالات خارجية. أنت المسؤول المباشر عن كل ما يخص التسويق: الاستراتيجية، المحتوى، الإعلانات، الـMedia Buying، الـCAC، الـFunnels، الـTracking، الـAcquisition، الـConversion، والتحسين المستمر للأداء.$$,
  $$ستكون مسؤولًا عن قيادة وظيفة التسويق بالكامل، من تحديد استراتيجية النمو وحتى تنفيذ الحملات وتحليل النتائج. ستعمل بشكل مباشر على: وضع استراتيجية التسويق والنمو للشركة، تحديد قنوات اكتساب العملاء المناسبة، إدارة الـMedia Buying والحملات الإعلانية، تحديد الميزانيات وتوزيعها ومراقبة الـCAC والـROAS، تطوير الأفكار التسويقية والـCreative Angles، تحليل أداء الإعلانات والمحتوى باستمرار، بناء وتحسين الـFunnels والـLanding Pages، تحسين الـLead Generation والـConversion Rate، إدارة استراتيجية الـContent Marketing بالتعاون مع فريق المحتوى، بناء الـOffers والرسائل التسويقية، تحليل بيانات العملاء والمبيعات لاتخاذ قرارات تسويقية، إنشاء Dashboards وتقارير أداء واضحة، اختبار أفكار وحملات جديدة باستمرار، اكتشاف فرص النمو وتحويلها إلى تجارب قابلة للقياس، وبناء نظام Marketing قابل للتوسع وليس الاعتماد على حملات منفردة.$$,
  $$شخص يفكر كـGrowth Marketer وليس كمنفذ إعلانات فقط. لديك قدرة قوية على ربط: Content → Acquisition → Funnel → Conversion → Revenue، وتستطيع الانتقال من التفكير الاستراتيجي إلى التنفيذ بنفسك. نبحث عن شخص لديه عقلية Owner، يهتم بالأرقام والنتائج، ويستطيع أن يقول بوضوح: "هذا هو الهدف، وهذه هي الأرقام التي نحتاجها، وهذه هي الخطة للوصول إليها."$$,
  $$خبرة قوية في Digital Marketing وGrowth Marketing. خبرة عملية في Meta Ads وMedia Buying. فهم قوي للـCAC وROAS وLTV وConversion Rate وFunnel Metrics. القدرة على تحليل البيانات واتخاذ قرارات بناءً عليها. خبرة في بناء وتحسين الـFunnels والـLanding Pages. فهم قوي للـContent Marketing والـCreative Strategy. القدرة على تطوير Offers ورسائل تسويقية قوية. خبرة في Tracking وPixels وAnalytics. القدرة على إدارة ميزانيات إعلانية وتحقيق نمو قابل للقياس. القدرة على العمل بشكل مستقل وتحمل مسؤولية النتائج. عقلية تجريبية تعتمد على Testing وليس التخمين.$$,
  $$بناء Marketing Strategy للشركة. إدارة جميع الحملات الإعلانية. إطلاق واختبار Campaigns وAd Sets وCreatives. تحليل CAC وROAS وRevenue بشكل مستمر. تحديد أفضل المنتجات والعروض والقنوات للنمو. تطوير أفكار إعلانية ومحتوى جديد. التعاون مع فريق Content وCreative لإنتاج المواد التسويقية. تحسين الـLanding Pages والـFunnels. بناء واختبار Acquisition Systems جديدة. متابعة رحلة العميل من أول مشاهدة للمحتوى أو الإعلان حتى الشراء. تحديد نقاط التسرب داخل الـFunnel والعمل على تحسينها. إعداد تقارير أسبوعية عن الأداء والفرص والمشكلات. وضع أهداف تسويقية واضحة وربطها بأهداف الإيرادات. تجربة قنوات واستراتيجيات جديدة عندما تحتاج الشركة إلى مصادر نمو إضافية. بناء نظام تسويق يمكن توسيعه مع نمو الشركة.$$,
  $$أنت Media Buyer فقط وتحتاج شخصًا آخر ليخبرك ماذا تفعل. أنت تعتمد على تنفيذ الـBrief فقط ولا تبني الاستراتيجية بنفسك. لا تعرف قراءة الأرقام وربطها بالإيرادات. ترى أن التسويق = إعلانات فقط. لا تستطيع تحمل مسؤولية النتائج. تنتظر التعليمات في كل خطوة. تخاف من اختبار أفكار جديدة أو إيقاف ما لا يعمل. اهتمامك الأساسي هو إدارة الأشخاص بدلًا من تحقيق النمو. لا تستطيع العمل بعقلية Owner. تبحث عن وظيفة روتينية.$$,
  true, now()
),
